```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    unsigned int forbidden[20] = {0};

    for (int i = 0; i < m; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        --x;
        --y;
        forbidden[x] |= 1u << y;
        forbidden[y] |= 1u << x;
    }

    unsigned int total = 1u << n;
    unsigned char *valid = calloc(total, sizeof(unsigned char));
    valid[0] = 1;

    long long count = 0;
    for (unsigned int mask = 1; mask < total; mask++) {
        unsigned int bit = mask & -mask;
        int vertex = 0;
        while ((1u << vertex) != bit) vertex++;

        unsigned int rest = mask ^ bit;
        if (valid[rest] && !(forbidden[vertex] & rest)) {
            valid[mask] = 1;
            count++;
        }
    }

    printf("%lld\n", count);
    free(valid);
    return 0;
}
